<?php $pageTitle='Players & CRM';require_once __DIR__.'/../includes/header.php';require_once __DIR__.'/../includes/sidebar.php';requireRole(['owner','manager','cashier','operator']);$db=getDB();$club=$_SESSION['club_id'];if($_SERVER['REQUEST_METHOD']==='POST'){verifyCsrf();$name=sanitize($_POST['name']??'');$phone=sanitize($_POST['phone']??'');if(!$name){$flash='Player name is required.';$error=true;}else{$db->prepare('INSERT INTO players(club_id,name,phone,email,tier,joined_date) VALUES(?,?,?,?,?,CURDATE())')->execute([$club,$name,$phone,filter_var($_POST['email']??'',FILTER_VALIDATE_EMAIL)?:null,in_array($_POST['tier']??'', ['regular','silver','gold','platinum'],true)?$_POST['tier']:'regular']);audit('player_created','players',(int)$db->lastInsertId());$flash='Player added successfully.';}}$term=trim($_GET['q']??'');$tier=$_GET['tier']??'';$sql='SELECT * FROM players WHERE club_id=? AND is_active=1';$params=[$club];if($term){$sql.=' AND (name LIKE ? OR phone LIKE ?)';$params[]='%'.$term.'%';$params[]='%'.$term.'%';}if(in_array($tier,['regular','silver','gold','platinum'],true)){$sql.=' AND tier=?';$params[]=$tier;}$sql.=' ORDER BY last_visit DESC,name LIMIT 100';$q=$db->prepare($sql);$q->execute($params);$players=$q->fetchAll(); ?><div class="flex flex-wrap gap-3 justify-between"><div><h1 class="text-2xl font-bold">Players & CRM</h1><p class="text-slate-400 text-sm mt-1">Manage members, loyalty, and club relationships.</p></div><button onclick="document.getElementById('add-player').classList.toggle('hidden')" class="btn-primary"><i class="fa-solid fa-user-plus mr-1"></i>Add Player</button></div><?php if(isset($flash)): ?><div class="mt-4 p-3 rounded-lg <?=$error??false?'bg-red-500/15 text-red-300':'bg-green-500/15 text-green-300'?>"><?=sanitize($flash)?></div><?php endif; ?><form id="add-player" method="post" class="card mt-5 hidden"><input type="hidden" name="csrf_token" value="<?=csrfToken()?>"><div class="grid md:grid-cols-4 gap-3"><div><label class="label">Name</label><input class="input" required name="name"></div><div><label class="label">Phone</label><input class="input" name="phone"></div><div><label class="label">Email</label><input class="input" type="email" name="email"></div><div><label class="label">Tier</label><select class="input" name="tier"><option value="regular">Regular</option><option value="silver">Silver</option><option value="gold">Gold</option><option value="platinum">Platinum</option></select></div></div><button class="btn-primary mt-4">Save Player</button></form><form class="card mt-5 flex flex-wrap gap-3"><input class="input max-w-sm" name="q" value="<?=sanitize($term)?>" placeholder="Search name or phone"><select class="input w-40" name="tier"><option value="">All tiers</option><?php foreach(['regular','silver','gold','platinum'] as $v):?><option <?=$tier===$v?'selected':''?> value="<?=$v?>"><?=ucfirst($v)?></option><?php endforeach?></select><button class="btn-secondary">Search</button></form><section class="card mt-5 overflow-x-auto"><table class="data-table w-full"><thead><tr><th>#</th><th>Name</th><th>Phone</th><th>Tier</th><th>Points</th><th>Total Spent</th><th>Last Visit</th><th></th></tr></thead><tbody><?php foreach($players as $p):?><tr><td><?=$p['id']?></td><td class="font-semibold"><?=sanitize($p['name'])?></td><td><?=sanitize($p['phone'])?></td><td><span class="px-2 py-1 rounded text-xs <?=$p['tier']==='gold'?'bg-amber-500/20 text-amber-300':($p['tier']==='platinum'?'bg-purple-500/20 text-purple-300':'bg-slate-700')?>"><?=ucfirst($p['tier'])?></span></td><td><?=$p['loyalty_points']?></td><td><?=money($p['total_spent'])?></td><td><?= $p['last_visit']?date('d M Y',strtotime($p['last_visit'])):'—'?></td><td><a class="text-green-400" href="<?=url('modules/player-profile.php?id='.$p['id'])?>">View</a></td></tr><?php endforeach;if(!$players):?><tr><td colspan="8" class="text-slate-500 text-center">No players found.</td></tr><?php endif?></tbody></table></section><?php require __DIR__.'/../includes/footer.php'; ?>
